7	/**
8	 * Interface for the ModelConfigService to break circular dependencies.
9	 */
10	export interface IModelConfigService {
11	  getModelDefinition(modelId: string):
12	    | {
13	        tier?: string;
14	        family?: string;
15	        isPreview?: boolean;
16	        displayName?: string;
17	        features?: {
18	          thinking?: boolean;
19	          multimodalToolUse?: boolean;
20	        };
21	      }
22	    | undefined;
23	}
